<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateThemeVO;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Holder\TemplateThemeAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TemplateThemeAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TemplateThemeAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getTheme returns null on a freshly created holder.
         */
        public function testThemeNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithTemplateThemeAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isThemeAssigned());
            $this->assertNull($holder->getTheme());
        }
}
class ImplWithTemplateThemeAttributeHolderUnitTest
{
  use TemplateThemeAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedThemeRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultTheme();
    }}
